155	// === PATH lookup ===
156	
157	/// Check whether an executable exists on the system PATH.
158	pub fn find_on_path(binary: &str) -> Option<PathBuf> {
159	    let path_var = std::env::var_os("PATH")?;
160	    let separator = if cfg!(windows) { ';' } else { ':' };
161	
162	    for dir in path_var.to_string_lossy().split(separator) {
163	        let candidate = Path::new(dir).join(binary);
164	        if candidate.is_file() {
165	            return Some(candidate);
166	        }
167	        // On Windows, also check with common extensions
168	        if cfg!(windows) {
169	            for ext in &[".exe", ".cmd", ".bat", ".com"] {
170	                let with_ext = Path::new(dir).join(format!("{}{}", binary, ext));
171	                if with_ext.is_file() {
172	                    return Some(with_ext);
173	                }
174	            }
175	        }
176	    }
177	    None
178	}
