1	//! Trust verification for remote extends URLs.
2	//!
3	//! This module provides a trust store that tracks which remote URLs
4	//! have been explicitly approved by the user. When a config uses
5	//! `extends:` with a remote URL, the trust store is checked before
6	//! fetching. Untrusted URLs require user confirmation (or the
7	//! `--trust` CLI flag).
8	//!
9	//! Trusted URLs are persisted in `~/.bivvy/trusted_urls.yml`.
10	
11	use anyhow::Result;
12	use serde::{Deserialize, Serialize};
13	use std::collections::HashSet;
14	use std::fs;
15	use std::path::PathBuf;
16	
17	/// Persistent store of trusted remote extends URLs.
18	#[derive(Debug, Clone, Default, Serialize, Deserialize)]
19	pub struct TrustStore {
20	    /// Set of URLs the user has explicitly trusted.
21	    #[serde(default)]
22	    pub urls: HashSet<String>,
23	}
24	
25	impl TrustStore {
26	    /// Get the default path for the trust store file.
27	    pub fn default_path() -> PathBuf {
28	        crate::sys::home_dir()
29	            .unwrap_or_else(|| PathBuf::from("~"))
30	            .join(".bivvy")
31	            .join("trusted_urls.yml")
32	    }
33	
34	    /// Load trusted URLs from the given path.
35	    pub fn load(path: &std::path::Path) -> Result<Self> {
36	        if !path.exists() {
37	            return Ok(Self::default());
38	        }
39	
40	        let content = fs::read_to_string(path)?;
41	        let store: Self = serde_yaml::from_str(&content)?;
42	        Ok(store)
43	    }
44	
45	    /// Load from the default path.
46	    pub fn load_default() -> Result<Self> {
47	        Self::load(&Self::default_path())
48	    }
49	
50	    /// Save trusted URLs to the given path.
51	    pub fn save(&self, path: &std::path::Path) -> Result<()> {
52	        if let Some(parent) = path.parent() {
53	            fs::create_dir_all(parent)?;
54	        }
55	
56	        let content = serde_yaml::to_string(self)?;
57	
58	        // Atomic write
59	        let temp_path = path.with_extension("yml.tmp");
60	        fs::write(&temp_path, &content)?;
61	        fs::rename(&temp_path, path)?;
62	
63	        Ok(())
64	    }
65	
66	    /// Save to the default path.
67	    pub fn save_default(&self) -> Result<()> {
68	        self.save(&Self::default_path())
69	    }
70	
71	    /// Check if a URL is trusted.
72	    pub fn is_trusted(&self, url: &str) -> bool {
73	        self.urls.contains(url)
74	    }
75	
76	    /// Add a URL to the trusted set.
77	    pub fn trust(&mut self, url: &str) {
78	        self.urls.insert(url.to_string());
79	    }
80	
81	    /// Remove a URL from the trusted set.
82	    pub fn revoke(&mut self, url: &str) {
83	        self.urls.remove(url);
84	    }
85	}
