180	// === Random bytes ===
181	
182	/// Fill a buffer with cryptographically secure random bytes.
183	#[cfg(unix)]
184	pub fn random_bytes(buf: &mut [u8]) {
185	    use std::io::Read;
186	    std::fs::File::open("/dev/urandom")
187	        .and_then(|mut f| f.read_exact(buf))
188	        .expect("Failed to read /dev/urandom");
189	}
190	
191	/// Fill a buffer with cryptographically secure random bytes.
192	#[cfg(windows)]
193	pub fn random_bytes(buf: &mut [u8]) {
194	    extern "system" {
195	        fn BCryptGenRandom(
196	            hAlgorithm: *mut std::ffi::c_void,
197	            pbBuffer: *mut u8,
198	            cbBuffer: u32,
199	            dwFlags: u32,
200	        ) -> i32;
201	    }
202	    const BCRYPT_USE_SYSTEM_PREFERRED_RNG: u32 = 0x00000002;
203	    let status = unsafe {
204	        BCryptGenRandom(
205	            std::ptr::null_mut(),
206	            buf.as_mut_ptr(),
207	            buf.len() as u32,
208	            BCRYPT_USE_SYSTEM_PREFERRED_RNG,
209	        )
210	    };
211	    assert!(status >= 0, "BCryptGenRandom failed with status {status}");
212	}
