//! Project index management.
//!
//! This module provides the [`ProjectIndex`] for tracking all known
//! projects that Bivvy has been used with.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;

use super::ProjectId;

/// Index of all known projects.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ProjectIndex {
    pub projects: HashMap<String, ProjectEntry>,
}

/// Entry for a project in the index.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProjectEntry {
    pub path: String,
    pub git_remote: Option<String>,
    pub name: String,
    pub last_accessed: DateTime<Utc>,
}

impl ProjectIndex {
    /// Get the index file path.
    pub fn file_path() -> PathBuf {
        crate::sys::home_dir()
            .unwrap_or_else(|| PathBuf::from("~"))
            .join(".bivvy")
            .join("projects")
            .join("index.yml")
    }

    /// Load the project index.
    pub fn load() -> crate::error::Result<Self> {
        let path = Self::file_path();

        if !path.exists() {
            return Ok(Self::default());
        }

        let content = fs::read_to_string(&path)?;
        let index: Self = serde_yaml::from_str(&content).map_err(|e| {
            crate::error::BivvyError::ConfigParseError {
                path,
                message: e.to_string(),
            }
        })?;

        Ok(index)
    }

    /// Save the project index using atomic write.
    ///
    /// Uses the write-to-temp-then-rename pattern to prevent corruption.
    pub fn save(&self) -> crate::error::Result<()> {
        let path = Self::file_path();

        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)?;
        }

        let content = serde_yaml::to_string(self).map_err(|e| {
            crate::error::BivvyError::ConfigValidationError {
                message: format!("Failed to serialize index: {}", e),
            }
        })?;

        // Atomic write: write to temp file, then rename
        let temp_path = path.with_extension("yml.tmp");
        fs::write(&temp_path, &content)?;
        fs::rename(&temp_path, &path)?;

        Ok(())
    }

    /// Update or add a project to the index.
    pub fn update(&mut self, project_id: &ProjectId) {
        let entry = ProjectEntry {
            path: project_id.path().to_string_lossy().to_string(),
            git_remote: project_id.git_remote().map(String::from),
            name: project_id.name().to_string(),
            last_accessed: Utc::now(),
        };
        self.projects.insert(project_id.hash().to_string(), entry);
    }

    /// Remove projects that no longer exist on disk.
    pub fn prune(&mut self) -> Vec<String> {
        let mut removed = Vec::new();

        self.projects.retain(|hash, entry| {
            let exists = std::path::Path::new(&entry.path).exists();
            if !exists {
                removed.push(hash.clone());
            }
            exists
        });

        removed
    }

    /// List all projects.
    pub fn list(&self) -> impl Iterator<Item = (&str, &ProjectEntry)> {
        self.projects.iter().map(|(k, v)| (k.as_str(), v))
    }

    /// Get a project by hash.
    pub fn get(&self, hash: &str) -> Option<&ProjectEntry> {
        self.projects.get(hash)
    }

    /// Number of tracked projects.
    pub fn len(&self) -> usize {
        self.projects.len()
    }

    /// Check if index is empty.
    pub fn is_empty(&self) -> bool {
        self.projects.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn project_index_default() {
        let index = ProjectIndex::default();
        assert!(index.is_empty());
    }

    #[test]
    fn project_index_update() {
        let temp = TempDir::new().unwrap();
        let project = ProjectId::from_path(temp.path()).unwrap();

        let mut index = ProjectIndex::default();
        index.update(&project);

        assert!(index.projects.contains_key(project.hash()));
        assert_eq!(index.len(), 1);
    }

    #[test]
    fn project_index_prune_removes_missing() {
        let mut index = ProjectIndex::default();
        index.projects.insert(
            "test".to_string(),
            ProjectEntry {
                path: "/nonexistent/path".to_string(),
                git_remote: None,
                name: "test".to_string(),
                last_accessed: Utc::now(),
            },
        );

        let removed = index.prune();
        assert!(removed.contains(&"test".to_string()));
        assert!(index.projects.is_empty());
    }

    #[test]
    fn project_index_prune_keeps_existing() {
        let temp = TempDir::new().unwrap();

        let mut index = ProjectIndex::default();
        index.projects.insert(
            "test".to_string(),
            ProjectEntry {
                path: temp.path().to_string_lossy().to_string(),
                git_remote: None,
                name: "test".to_string(),
                last_accessed: Utc::now(),
            },
        );

        let removed = index.prune();
        assert!(removed.is_empty());
        assert_eq!(index.len(), 1);
    }

    #[test]
    fn project_index_list() {
        let temp = TempDir::new().unwrap();
        let project = ProjectId::from_path(temp.path()).unwrap();

        let mut index = ProjectIndex::default();
        index.update(&project);

        let entries: Vec<_> = index.list().collect();
        assert_eq!(entries.len(), 1);
    }

    #[test]
    fn project_index_get() {
        let temp = TempDir::new().unwrap();
        let project = ProjectId::from_path(temp.path()).unwrap();

        let mut index = ProjectIndex::default();
        index.update(&project);

        assert!(index.get(project.hash()).is_some());
        assert!(index.get("nonexistent").is_none());
    }

    #[test]
    fn project_entry_serializes() {
        let entry = ProjectEntry {
            path: "/path/to/project".to_string(),
            git_remote: Some("https://github.com/test/repo".to_string()),
            name: "project".to_string(),
            last_accessed: Utc::now(),
        };

        let yaml = serde_yaml::to_string(&entry).unwrap();
        assert!(yaml.contains("project"));
        assert!(yaml.contains("github.com"));
    }
}

//! Snapshot and baseline management for change checks.
//!
//! The [`SnapshotStore`] manages baseline hashes used by change checks
//! to detect whether targets have changed. Baselines can be:
//! - Per-run (updated after each successful step execution)
//! - Named snapshots (captured via `bivvy snapshot <slug>`)
//!
//! Snapshots are stored per-project in `~/.bivvy/projects/{project_hash}/snapshots/`.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

/// Describes what happened when a baseline was recorded.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BaselineChange {
    /// A new baseline was established (no previous value existed).
    Established,
    /// The baseline was updated (previous hash differed).
    Updated {
        /// The previous hash value.
        old_hash: String,
    },
    /// The baseline hash was unchanged.
    Unchanged,
}

/// Key for looking up baselines in the snapshot store.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct SnapshotKey {
    /// Step name.
    pub step_name: String,
    /// Scope: "project" (default) or "workflow:{name}".
    pub scope: String,
    /// Hash of the step's check configuration. Ensures different
    /// check configs produce isolated baselines.
    pub config_hash: String,
}

impl SnapshotKey {
    /// Create a project-scoped key.
    pub fn project(step_name: impl Into<String>, config_hash: impl Into<String>) -> Self {
        Self {
            step_name: step_name.into(),
            scope: "project".to_string(),
            config_hash: config_hash.into(),
        }
    }

    /// Create a workflow-scoped key.
    pub fn workflow(
        step_name: impl Into<String>,
        workflow_name: impl Into<String>,
        config_hash: impl Into<String>,
    ) -> Self {
        Self {
            step_name: step_name.into(),
            scope: format!("workflow:{}", workflow_name.into()),
            config_hash: config_hash.into(),
        }
    }

    /// Returns the filename for this key's storage.
    fn filename(&self) -> String {
        if self.scope == "project" {
            format!("{}_{}.yml", self.step_name, self.config_hash)
        } else {
            let workflow = self.scope.strip_prefix("workflow:").unwrap_or("unknown");
            format!(
                "{}_{}__wf_{}.yml",
                self.step_name, self.config_hash, workflow
            )
        }
    }
}

/// Information about a single baseline.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BaselineEntry {
    /// The computed hash.
    pub hash: String,
    /// When this baseline was captured.
    pub captured_at: String,
    /// What was hashed.
    pub target: String,
}

/// Stored snapshot data for a step.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct SnapshotData {
    /// Step name.
    pub step: String,
    /// Scope.
    pub scope: String,
    /// Named and run-based baselines.
    #[serde(default)]
    pub baselines: HashMap<String, BaselineEntry>,
}

/// Information about a named snapshot for listing.
#[derive(Debug, Clone)]
pub struct SnapshotInfo {
    /// The snapshot slug.
    pub slug: String,
    /// Step name.
    pub step: String,
    /// Target that was hashed.
    pub target: String,
    /// Hash value.
    pub hash: String,
    /// When captured.
    pub captured_at: String,
}

/// A recorded baseline change, for event emission.
#[derive(Debug, Clone)]
pub struct BaselineEvent {
    /// Step name.
    pub step: String,
    /// What was hashed (file path, glob, command).
    pub target: String,
    /// New hash value.
    pub hash: String,
    /// Scope ("project" or "workflow:<name>").
    pub scope: String,
    /// What kind of change occurred.
    pub change: BaselineChange,
}

/// Manages baseline hashes for change check comparisons.
///
/// The store reads/writes YAML files in a snapshots directory.
/// Each step+config combination gets its own file.
pub struct SnapshotStore {
    /// Directory where snapshot files are stored.
    dir: PathBuf,
    /// In-memory cache of loaded snapshot data.
    cache: HashMap<String, SnapshotData>,
    /// Pending baseline changes for event emission.
    pending_events: Vec<BaselineEvent>,
}

impl SnapshotStore {
    /// Create a new store backed by the given directory.
    pub fn new(dir: impl Into<PathBuf>) -> Self {
        Self {
            dir: dir.into(),
            cache: HashMap::new(),
            pending_events: Vec::new(),
        }
    }

    /// Create an empty in-memory store not backed by any directory.
    ///
    /// Useful when check evaluation doesn't need snapshot storage
    /// (e.g., evaluating presence or execution checks only).
    /// Change checks evaluated against this store will always get
    /// `None` baselines (indeterminate results).
    pub fn empty() -> Self {
        Self {
            dir: PathBuf::new(),
            cache: HashMap::new(),
            pending_events: Vec::new(),
        }
    }

    /// Load or create a snapshot store for a project.
    ///
    /// Uses `~/.bivvy/projects/{project_hash}/snapshots/` as the storage
    /// directory, matching the state store's project isolation scheme.
    pub fn load_for_project(project_id: &crate::state::ProjectId) -> Self {
        let dir = crate::sys::home_dir()
            .unwrap_or_else(|| PathBuf::from("~"))
            .join(".bivvy")
            .join("projects")
            .join(project_id.hash())
            .join("snapshots");
        Self::new(dir)
    }

    /// Get the baseline hash for a change check.
    ///
    /// The `baseline_name` parameter selects which baseline to compare against:
    /// - `"_last_run"` for `each_run` baseline config
    /// - `"_first_run"` for `first_run` baseline config
    /// - A named slug for `snapshot:<slug>` baseline config
    pub fn get_baseline(&mut self, key: &SnapshotKey, baseline_name: &str) -> Option<String> {
        self.ensure_loaded(key);
        let filename = key.filename();
        self.cache
