    result = TOKEN_REGEX.replace_all(&result, "[REDACTED]").to_string();

    // Truncate
    if result.len() > MAX_ERROR_LENGTH {
        result.truncate(MAX_ERROR_LENGTH);
        result.push_str("...[truncated]");
