        fs::write(
            workflows_dir.join("greet.yml"),
            r#"
steps:
  hello:
    command: "workflow"
workflow:
  steps:
    - hello
"#,
        )
        .unwrap();

        fs::write(
            bivvy.join("config.local.yml"),
            r#"
steps:
  hello:
    command: "local override"
"#,
        )
        .unwrap();

        let config = load_for_run(temp.path(), "greet").unwrap();
        assert_eq!(
            config.steps["hello"].execution.command,
