  command: "echo test"
"#;
        fs::write(templates_dir.join("test.yml"), template_yaml).unwrap();

        let loader = LocalLoader::new(Some(temp.path())).unwrap();
        let (_, source) = loader.get_with_source("test").unwrap();
        assert_eq!(source, TemplateSource::Project);
